int read_index_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    git_index_entry *entry;
    size_t entry_size;

    if (buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    entry = (git_index_entry *)malloc(sizeof(git_index_entry));
    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, sizeof(git_index_entry));
    entry_size = sizeof(git_index_entry);

    if (entry->flags_extended & GIT_IDXENTRY_CASE) {
        // Handle case sensitivity
        entry->flags |= GIT_IDXENTRY_CASE;
    }

    if (entry->flags & GIT_IDXENTRY_HASH) {
        // Handle hash
        if (buffer_size < entry_size + 20) {
            free(entry);
            return -1;
        }
        entry_size += 20;
    }

    if (entry->flags & GIT_IDXENTRY_UTF8) {
        // Handle UTF-8 path
        size_t path_len = strlen((const char *)buffer + sizeof(git_index_entry)) + 1;
        if (buffer_size < entry_size + path_len) {
            free(entry);
            return -1;
        }
        char *path = (char *)malloc(path_len);
        if (!path) {
            free(entry);
            return -1;
        }
        memcpy(path, (const char *)buffer + sizeof(git_index_entry), path_len);
        entry->path = path;
    } else {
        // Handle non-UTF-8 path
        size_t path_len = strlen((const char *)buffer + sizeof(git_index_entry)) + 1;
        if (buffer_size < entry_size + path_len) {
            free(entry);
            return -1;
        }
        size_t full_path_len = strlen(last) + path_len + 1;
        char *full_path = (char *)malloc(full_path_len);
        if (!full_path) {
            free(entry);
            return -1;
        }
        snprintf(full_path, full_path_len, "%s/%s", last, (const char *)buffer + sizeof(git_index_entry));
        entry->path = full_path;
    }

    *out = entry;
    *out_size = entry_size;

    return 0;
}

