    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, sizeof(git_index_entry));

    path = (const char *)((const char *)buffer + sizeof(git_index_entry));
    path_len = strlen(path) + 1;

    if (entry->flags & GIT_INDEX_ENTRY_OWNERLO) {
        char *new_path = NULL;
        if (last) {
            size_t new_len = strlen(last) + path_len;
            new_path = (char *)malloc(new_len);
            if (!new_path) {
                free(entry);
                return -1;
            }
            snprintf(new_path, new_len, "%s%s", last, path);
            path = new_path;
        }
    }

    if (entry->flags & GIT_INDEX_ENTRY_OWNERHI) {
        char *decompressed_path = decompress_path(path, path_len);
        if (!decompressed_path) {
            free(entry);
            return -1;
        }
        path = decompressed_path;
    }

    entry->path = strdup(path);
    if (!entry->path) {
        free(entry);
        return -1;
    }

    *out = entry;
    *out_size = sizeof(git_index_entry) + path_len;
    return 0;
