int read_index_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    git_index_entry *entry;
    size_t entry_size;

    if (buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    entry = (git_index_entry *)malloc(sizeof(git_index_entry));
    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, sizeof(git_index_entry));

    if (entry->flags & GIT_INDEX_ENTRY_UPTODATE) {
        if (entry->file_size != 0) {
            free(entry);
            return -1;
        }
    }

    if (entry->flags & GIT_INDEX_ENTRY_ASSUMED_VALID) {
        if (entry->file_size != 0) {
            free(entry);
            return -1;
        }
    }

    if (last) {
        size_t path_length = strlen(last) + 1;
        entry->path = (char *)malloc(path_length);
        if (!entry->path) {
            free(entry);
            return -1;
        }
        strcpy((char *)entry->path, last);
    } else {
        entry->path = (char *)buffer + sizeof(git_index_entry);
    }

    entry_size = sizeof(git_index_entry) + strlen(entry->path) + 1;

    if (buffer_size < entry_size) {
        free(entry->path);
        free(entry);
        return -1;
    }

    *out = entry;
    *out_size = entry_size;
    return 0;
}

int git_index_read_entry(git_index_entry **out, size_t *out_size, git_index *index, const void *buffer, size_t buffer_size, const char *last) {
    if (buffer_size < sizeof(git_index_entry)) {
        return -1;
    }

    git_index_entry *entry = (git_index_entry *)malloc(buffer_size);
    if (!entry) {
        return -1;
    }

    memcpy(entry, buffer, buffer_size);

    size_t path_len = 0;
    if (entry->flags & GIT_INDEX_ENTRY_FLAG_UPTODATE) {
        path_len = entry->pathlen;
    } else {
        path_len = strlen(last) + 1;
    }

    if ((entry->flags & GIT_INDEX_ENTRY_FLAG_UPTODATE) != 0 && entry->pathlen != path_len) {
        free(entry);
        return -1;
    }

    entry->path = (char *)malloc(path_len);
    if (!entry->path) {
        free(entry);
        return -1;
    }

    if (entry->flags & GIT_INDEX_ENTRY_FLAG_UPTODATE) {
        memcpy(entry->path, last, path_len);
    } else {
        snprintf(entry->path, path_len, "%s", last);
    }

    *out = entry;
    *out_size = buffer_size;

    return 0;
}

